SET NOCOUNT ON;
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'profile/compatibility' AS [key],CONVERT(nvarchar(max),compatibility_level) AS [value] FROM sys.databases WHERE database_id=DB_ID()) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'profile/snapshot',CONVERT(nvarchar(max),snapshot_isolation_state) FROM sys.databases WHERE database_id=DB_ID()) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'profile/collation',CONVERT(nvarchar(max),DATABASEPROPERTYEX(DB_NAME(),'Collation'))) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'profile/major',CONVERT(nvarchar(max),SERVERPROPERTY('ProductMajorVersion'))) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'table/'+s.name+'/'+t.name,N'' FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE t.is_ms_shipped=0) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'column/'+s.name+'/'+t.name+'/'+c.name,CONCAT(ty.name,'|',c.max_length,'|',c.precision,'|',c.scale,'|',c.is_nullable,'|',c.is_identity,'|',c.is_computed,'|',ISNULL(c.collation_name,'')) FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE t.is_ms_shipped=0) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'key/'+s.name+'/'+t.name+'/'+k.name,CONCAT(k.type,'|',(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name),',') WITHIN GROUP(ORDER BY ic.key_ordinal) FROM sys.index_columns ic JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE ic.object_id=k.parent_object_id AND ic.index_id=k.unique_index_id)) FROM sys.key_constraints k JOIN sys.tables t ON t.object_id=k.parent_object_id JOIN sys.schemas s ON s.schema_id=t.schema_id) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'index/'+s.name+'/'+t.name+'/'+i.name,CONCAT(i.type,'|',i.is_unique,'|',i.is_primary_key,'|',i.is_unique_constraint,'|',i.is_disabled,'|',ISNULL(i.filter_definition,''),'|',(SELECT STRING_AGG(CONVERT(nvarchar(max),CONCAT(c.name,':',ic.is_descending_key,':',ic.is_included_column)),',') WITHIN GROUP(ORDER BY ic.key_ordinal,ic.index_column_id) FROM sys.index_columns ic JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE ic.object_id=i.object_id AND ic.index_id=i.index_id)) FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE t.is_ms_shipped=0 AND i.index_id>0) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'fk/'+s.name+'/'+t.name+'/'+f.name,CONCAT(rs.name,'.',rt.name,'|',f.delete_referential_action,'|',f.update_referential_action,'|',f.is_disabled,'|',f.is_not_trusted,'|',(SELECT STRING_AGG(CONVERT(nvarchar(max),CONCAT(pc.name,':',rc.name)),',') WITHIN GROUP(ORDER BY fc.constraint_column_id) FROM sys.foreign_key_columns fc JOIN sys.columns pc ON pc.object_id=fc.parent_object_id AND pc.column_id=fc.parent_column_id JOIN sys.columns rc ON rc.object_id=fc.referenced_object_id AND rc.column_id=fc.referenced_column_id WHERE fc.constraint_object_id=f.object_id)) FROM sys.foreign_keys f JOIN sys.tables t ON t.object_id=f.parent_object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.tables rt ON rt.object_id=f.referenced_object_id JOIN sys.schemas rs ON rs.schema_id=rt.schema_id) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'check/'+s.name+'/'+t.name+'/'+c.name,CONCAT(c.is_disabled,'|',c.is_not_trusted,'|',c.definition) FROM sys.check_constraints c JOIN sys.tables t ON t.object_id=c.parent_object_id JOIN sys.schemas s ON s.schema_id=t.schema_id) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'default/'+s.name+'/'+t.name+'/'+c.name,CONVERT(nvarchar(max),d.definition) FROM sys.default_constraints d JOIN sys.tables t ON t.object_id=d.parent_object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id AND c.column_id=d.parent_column_id) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'module/'+s.name+'/'+o.name,CONVERT(nvarchar(max),m.definition) FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.is_ms_shipped=0 AND o.type IN('TR','V','FN','IF','P')) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'module-kind/'+s.name+'/'+o.name,CONVERT(nvarchar(max),o.type) FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.is_ms_shipped=0 AND o.type IN('TR','V','FN','IF','P')) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'trigger/'+s.name+'/'+o.name,CONCAT(t.is_disabled,'|',ps.name,'.',p.name,'|',(SELECT STRING_AGG(CONVERT(nvarchar(max),type_desc),',') WITHIN GROUP(ORDER BY type_desc) FROM sys.trigger_events WHERE object_id=t.object_id)) FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.objects p ON p.object_id=t.parent_id JOIN sys.schemas ps ON ps.schema_id=p.schema_id WHERE t.is_ms_shipped=0) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'parameter/'+s.name+'/'+o.name+'/'+CONVERT(varchar(12),p.parameter_id),CONCAT(p.name,'|',ty.name,'|',p.max_length,'|',p.precision,'|',p.scale,'|',p.is_output) FROM sys.parameters p JOIN sys.objects o ON o.object_id=p.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.types ty ON ty.user_type_id=p.user_type_id WHERE o.is_ms_shipped=0 AND o.type IN('FN','IF','P')) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'result-column/'+s.name+'/'+o.name+'/'+CONVERT(varchar(12),c.column_id),CONCAT(c.name,'|',ty.name,'|',c.max_length,'|',c.precision,'|',c.scale,'|',c.is_nullable,'|',ISNULL(c.collation_name,'')) FROM sys.columns c JOIN sys.objects o ON o.object_id=c.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE o.is_ms_shipped=0 AND o.type IN('V','IF')) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'migration/'+MigrationId,CONVERT(nvarchar(max),ProductVersion) FROM dbo.__EFMigrationsHistory) AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'role/'+name,CONCAT(type,'|',is_fixed_role,'|',USER_NAME(owning_principal_id)) FROM sys.database_principals WHERE name LIKE 'ec[_]%') AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'permission/'+r.name+'/'+CONVERT(varchar(12),p.class)+'/'+ISNULL(OBJECT_SCHEMA_NAME(p.major_id),'')+'/'+ISNULL(OBJECT_NAME(p.major_id),'')+'/'+CONVERT(varchar(12),p.minor_id)+'/'+p.permission_name,CONVERT(nvarchar(max),p.state) FROM sys.database_permissions p JOIN sys.database_principals r ON r.principal_id=p.grantee_principal_id WHERE r.name LIKE 'ec[_]%') AS facts([key],[value]);
SELECT [key] COLLATE DATABASE_DEFAULT AS [key],[value] COLLATE DATABASE_DEFAULT AS [value] FROM (SELECT 'role-parent/'+r.name+'/'+parent.name,N'' FROM sys.database_role_members m JOIN sys.database_principals r ON r.principal_id=m.member_principal_id JOIN sys.database_principals parent ON parent.principal_id=m.role_principal_id WHERE r.name LIKE 'ec[_]%') AS facts([key],[value]);
